Per-tenant, per-limit counters make `charge` and `refund` proportional to the number of limits, not to the history. Validation runs before any mutation, and the whole check-and-update sits under a lock, so concurrent callers cannot jointly exceed a cap. The `RescanGuard` oracle shares no code with the guard, so agreement across thousands of random operations is strong evidence of correctness, and the threaded test confirms exactly 200 of 400 one-token charges succeed against a cap of 200.

**`budget/guard.py`**

```python
from __future__ import annotations

import itertools
import threading
from collections import defaultdict
from collections.abc import Mapping
from dataclasses import dataclass


class BudgetExceededError(Exception):
    def __init__(self, tenant: str, limit: str) -> None:
        super().__init__(f"{tenant} would exceed the {limit} limit")
        self.tenant, self.limit = tenant, limit


class UnknownCallError(Exception):
    """refund() was called for a call id that does not exist or was already refunded."""


@dataclass(frozen=True)
class _Call:
    tenant: str
    usage: tuple[tuple[str, int], ...]


class BudgetGuard:
    """Per-tenant running counters: charge and refund are O(number of limits), never O(history)."""

    def __init__(self, caps: Mapping[str, int]) -> None:
        self._caps = dict(caps)
        self._used: dict[str, dict[str, int]] = defaultdict(lambda: defaultdict(int))
        self._calls: dict[int, _Call] = {}
        self._ids = itertools.count(1)
        self._lock = threading.Lock()

    def charge(self, tenant: str, usage: Mapping[str, int]) -> int:
        for name, amount in usage.items():
            if name not in self._caps:
                raise ValueError(f"unknown limit: {name}")
            if amount < 0:
                raise ValueError("usage must be non-negative")
        with self._lock:                         # check-then-act must be one atomic step
            used = self._used[tenant]
            for name, amount in usage.items():   # validate everything first ...
                if used[name] + amount > self._caps[name]:
                    raise BudgetExceededError(tenant, name)
            for name, amount in usage.items():   # ... then mutate
                used[name] += amount
            call_id = next(self._ids)
            self._calls[call_id] = _Call(tenant, tuple(sorted(usage.items())))
            return call_id

    def refund(self, call_id: int) -> None:
        with self._lock:
            call = self._calls.pop(call_id, None)
            if call is None:
                raise UnknownCallError(call_id)
            for name, amount in call.usage:
                self._used[call.tenant][name] -= amount

    def used(self, tenant: str, limit: str) -> int:
        with self._lock:
            return self._used[tenant][limit] if tenant in self._used else 0


class RescanGuard:
    """The slow, obviously correct oracle: recompute usage from the full history."""

    def __init__(self, caps: Mapping[str, int]) -> None:
        self._caps = dict(caps)
        self._calls: dict[int, tuple[str, dict[str, int]]] = {}
        self._ids = itertools.count(1)

    def used(self, tenant: str, limit: str) -> int:
        return sum(u.get(limit, 0) for t, u in self._calls.values() if t == tenant)

    def charge(self, tenant: str, usage: Mapping[str, int]) -> int:
        for name, amount in usage.items():
            if self.used(tenant, name) + amount > self._caps[name]:
                raise BudgetExceededError(tenant, name)
        call_id = next(self._ids)
        self._calls[call_id] = (tenant, dict(usage))
        return call_id

    def refund(self, call_id: int) -> None:
        if self._calls.pop(call_id, None) is None:
            raise UnknownCallError(call_id)
```

**`tests/test_guard.py`**

```python
import random
import threading

import pytest

from budget.guard import BudgetExceededError, BudgetGuard, RescanGuard, UnknownCallError

CAPS = {"tokens": 100, "calls": 5}


def test_charge_and_refund_update_usage() -> None:
    guard = BudgetGuard(CAPS)
    first = guard.charge("acme", {"tokens": 60, "calls": 1})
    assert guard.used("acme", "tokens") == 60
    guard.refund(first)
    assert guard.used("acme", "tokens") == 0 and guard.used("acme", "calls") == 0


def test_a_rejected_charge_changes_nothing_in_any_limit() -> None:
    guard = BudgetGuard(CAPS)
    guard.charge("acme", {"tokens": 90, "calls": 1})
    with pytest.raises(BudgetExceededError):
        guard.charge("acme", {"tokens": 20, "calls": 1})      # tokens would exceed, calls would not
    assert guard.used("acme", "tokens") == 90 and guard.used("acme", "calls") == 1


def test_tenants_are_isolated_and_refund_is_single_use() -> None:
    guard = BudgetGuard(CAPS)
    call = guard.charge("acme", {"tokens": 100})
    guard.charge("globex", {"tokens": 100})                   # a different tenant has its own budget
    guard.refund(call)
    with pytest.raises(UnknownCallError):
        guard.refund(call)


def test_fast_guard_agrees_with_rescan_oracle_on_random_operations() -> None:
    rng = random.Random(11)
    for _ in range(200):
        fast, slow = BudgetGuard(CAPS), RescanGuard(CAPS)
        live: list[tuple[int, int]] = []
        for _ in range(40):
            if live and rng.random() < 0.3:
                fast_id, slow_id = live.pop(rng.randrange(len(live)))
                fast.refund(fast_id)
                slow.refund(slow_id)
            else:
                tenant = rng.choice(["a", "b"])
                usage = {"tokens": rng.randint(0, 40), "calls": rng.randint(0, 2)}
                results = []
                for guard in (fast, slow):
                    try:
                        results.append(guard.charge(tenant, usage))
                    except BudgetExceededError as exc:
                        results.append(exc.limit)
                assert isinstance(results[0], int) == isinstance(results[1], int)
                if isinstance(results[0], int):
                    live.append((results[0], results[1]))
            for tenant in ("a", "b"):
                for limit in CAPS:
                    assert fast.used(tenant, limit) == slow.used(tenant, limit)


def test_concurrent_charges_never_exceed_the_cap() -> None:
    guard = BudgetGuard({"tokens": 200})
    successes = []

    def worker() -> None:
        ok = 0
        for _ in range(50):
            try:
                guard.charge("acme", {"tokens": 1})
                ok += 1
            except BudgetExceededError:
                pass
        successes.append(ok)

    threads = [threading.Thread(target=worker) for _ in range(8)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert sum(successes) == 200 and guard.used("acme", "tokens") == 200
```

